// ---------------------------------------------------------------------------
// EDIT THIS NODE AND NOTHING ELSE.
// Every node downstream reads its configuration from here.
// ---------------------------------------------------------------------------
return [
  {
    json: {
      config: {
        // Where every website enquiry lands. One mailbox, on purpose: this
        // workflow notifies, it does not assign. Whoever picks it up replies.
        notifyEmail: 'outreach@apmgmaintenance.com.au',

        businessName: 'Commercial Painters',
        businessPhone: '1300 97 97 40',
        timezone: 'Australia/Melbourne',
      },
    },
  },
];

// ---------------------------------------------------------------------------
// Turn the website's enquiry into one email.
//
// The site validates before it posts and refuses bots before it posts, but a
// webhook URL is public and anything can call it, so the cheap checks are
// repeated here. Nothing is inferred and nothing is corrected: a payload that
// does not look like an enquiry is refused rather than emailed half-empty.
// ---------------------------------------------------------------------------

const cfg = $('Settings').first().json.config;
const incoming = $('Enquiry received').first().json;
const body = incoming.body ?? incoming;

const text = (value) => String(value ?? '').trim();

// Mirrors COMMERCIAL_PROPERTY_TYPES in lib/enquiry/options.ts. The site posts
// the value; the email reads the label, because "Aged care or retirement
// living" is what somebody triaging an inbox needs to see.
const PROPERTY_TYPES = {
  'education-and-childcare': 'School or childcare',
  healthcare: 'Healthcare or medical',
  'aged-care-and-retirement': 'Aged care or retirement living',
  'body-corporate-and-strata': 'Body corporate or strata',
  retail: 'Retail',
  hospitality: 'Hospitality or venue',
  'leisure-and-sports': 'Leisure or sports facility',
  industrial: 'Industrial or warehouse',
  office: 'Office',
  other: 'Something else',
};

const enquiry = {
  name: text(body.name),
  email: text(body.email).toLowerCase(),
  phone: text(body.phone),
  suburb: text(body.suburb),
  propertyType: text(body.propertyType),
  sector: PROPERTY_TYPES[text(body.propertyType)] ?? '',
};

// The honeypot the site renders off-screen. Named to stay clear of browser
// autofill: see components/forms/fields.tsx.
const problems = [];
if (text(body.referral_source)) problems.push('honeypot filled');
if (enquiry.name.length < 2) problems.push('missing name');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(enquiry.email)) problems.push('missing or invalid email');
if (enquiry.phone.replace(/\D/g, '').length < 8) problems.push('missing or invalid phone');
if (enquiry.suburb.length < 2) problems.push('missing suburb');
if (!enquiry.sector) problems.push('missing or unknown sector');

const received = DateTime.now()
  .setZone(cfg.timezone)
  .setLocale('en-AU')
  .toFormat("cccc d LLLL yyyy 'at' h:mm a");

const subject = `Website enquiry - ${enquiry.name} - ${enquiry.sector}, ${enquiry.suburb}`;

const message = [
  'A new enquiry came in from the website.',
  '',
  `Name:    ${enquiry.name}`,
  `Phone:   ${enquiry.phone}`,
  `Email:   ${enquiry.email}`,
  `Suburb:  ${enquiry.suburb}`,
  `Sector:  ${enquiry.sector}`,
  '',
  `Received ${received} (Melbourne time).`,
  '',
  'They asked for a free site assessment, so the next step is a call to arrange',
  'a time - on site in Melbourne, or a short online call anywhere else.',
  '',
  `Reply to this email to answer ${enquiry.name} directly, or call ${enquiry.phone}.`,
].join('\n');

return [
  {
    json: {
      route: problems.length ? 'reject' : 'send',
      problems,
      enquiry,
      config: cfg,
      subject,
      message,
    },
  },
];
